import { readFileSync } from "node:fs";

import { describe, expect, it } from "vite-plus/test";

import { OUTPUT, readMigrationFiles, renderMigrations } from "../src/migrations.ts";

describe("renderMigrations", () => {
  it("embeds each file as its version, name and breakpoint-separated statements", () => {
    const sql = "CREATE TABLE `a` (\n\t`id` text\n);\n--> statement-breakpoint\nCREATE INDEX `i` ON `a` (`id`);";
    expect(renderMigrations([{ file: "0001_init.sql", sql }])).toBe(
      [
        "// Generated by tools/gen/src/migrations.ts from packages/db/migrations/*.sql. Do not edit.",
        'import type { Migration } from "./migrator.ts";',
        "",
        "export const MIGRATIONS: readonly [Migration, ...Migration[]] = [",
        "  {",
        "    version: 1,",
        '    name: "init",',
        "    statements: [",
        '      "CREATE TABLE `a` (\\n\\t`id` text\\n);",',
        '      "CREATE INDEX `i` ON `a` (`id`);",',
        "    ],",
        "  },",
        "];",
        "",
      ].join("\n"),
    );
  });

  it("quotes as Oxfmt does, so the output passes `vp check`", () => {
    const out = renderMigrations([
      { file: "0001_a.sql", sql: `CHECK("t"."q" >= 0)--> statement-breakpoint\nWHERE s = 'x' AND "t" = 'y'` },
    ]);
    expect(out).toContain(`      'CHECK("t"."q" >= 0)',\n`);
    expect(out).toContain(`      "WHERE s = 'x' AND \\"t\\" = 'y'",\n`);
  });

  it("orders files by version", () => {
    const out = renderMigrations([
      { file: "0002_b.sql", sql: "SELECT 2" },
      { file: "0001_a.sql", sql: "SELECT 1" },
    ]);
    expect(out.indexOf('name: "a"')).toBeLessThan(out.indexOf('name: "b"'));
  });

  it.each([
    [[{ file: "init.sql", sql: "" }], "init.sql: expected version 1"],
    [[{ file: "0002_b.sql", sql: "" }], "0002_b.sql: expected version 1"],
    [
      [
        { file: "0001_a.sql", sql: "" },
        { file: "0003_c.sql", sql: "" },
      ],
      "0003_c.sql: expected version 2",
    ],
  ])("refuses a misnamed file or a gap in versions", (files, message) => {
    expect(() => renderMigrations(files)).toThrow(message);
  });

  it("the committed migrations.generated.ts is fresh (run `pnpm gen:migrations`)", () => {
    expect(readFileSync(OUTPUT, "utf8")).toBe(renderMigrations(readMigrationFiles()));
  });
});
